import type { ProjectEntry } from '../data/projects.ts';
import { prefersReducedMotion } from './motion.ts';

/** MIME type for a project video, from its extension. */
export function videoType(src: string): string {
    return src.split('.').pop()?.toLowerCase() === 'webm' ? 'video/webm' : 'video/mp4';
}

/** Poster next to the video: demo.mp4 -> demo.poster.webp (generated by `npm run media:posters`). */
export function videoPoster(src: string): string {
    return src.replace(/\.[^./]+$/, '.poster.webp');
}

/** The still shown for a project before anything plays: a video's poster, an image, or a gallery's first picture. */
export const still = (p: ProjectEntry): string =>
    p.media.type === 'video'
        ? videoPoster(p.media.src)
        : p.media.type === 'image'
          ? p.media.src
          : p.media.images[0].src;

let observer: IntersectionObserver | undefined;
const onScreen = new Set<HTMLVideoElement>();
let tabListening = false;

/**
 * Play the videos under `root` only while they are on (or near) screen and the tab is shown, and pause them otherwise.
 * Videos are rendered with preload="none", so nothing downloads until a video first comes into view.
 * With reduced motion, videos never autoplay and keep showing their poster.
 */
export function playVideosWhenVisible(root: ParentNode): void {
    observer?.disconnect();
    onScreen.clear();
    if (prefersReducedMotion()) return;
    if (!tabListening) {
        tabListening = true;
        document.addEventListener('visibilitychange', () => {
            for (const video of onScreen)
                if (document.hidden) video.pause();
                else video.play().catch(() => {});
        });
    }

    observer = new IntersectionObserver(
        (entries) => {
            for (const entry of entries) {
                const video = entry.target as HTMLVideoElement;
                if (entry.isIntersecting) {
                    onScreen.add(video);
                    if (!document.hidden) video.play().catch(() => {}); // autoplay can be refused (e.g. data saver); the poster stays
                } else {
                    onScreen.delete(video);
                    video.pause();
                }
            }
        },
        { rootMargin: '200px 0px' }
    );
    root.querySelectorAll('video').forEach((video) => observer?.observe(video));
}
